input.command:
tail -n +2 transactions.csv | awk -F, '
BEGIN{r["EUR"]=1.00; r["USD"]=0.92; r["GBP"]=1.17}
{ e=sprintf("%.2f", $5*r[$6]+0.0000001); c[$3]+=e; m[substr($2,1,7)]+=e; t+=e; n++; if(e+0>mx) mx=e+0 }
END{
  printf "total=%.2f n=%d mean=%.2f max=%.2f\n", t, n, t/n, mx
  printf "may=%.1f jun=%.1f travel_share=%.1f\n", (m["2026-05"]-m["2026-04"])/m["2026-04"]*100, (m["2026-06"]-m["2026-05"])/m["2026-05"]*100, c["travel"]/t*100
  for(k in c) printf "  %s=%.2f\n", k, c[k]
}' | sort
echo "=== halfway-cent check (values landing exactly on a half-cent) ===" 
tail -n +2 transactions.csv | awk -F, 'BEGIN{r["EUR"]=1.00;r["USD"]=0.92;r["GBP"]=1.17}{v=$5*r[$6]*1000; if (int(v)%10==5) print "TIE:", $0}'
echo "(no TIE lines above = rounding mode is irrelevant)"
echo "=== final file ===" && cat RESULTS.json && python3 -c "import json;d=json.load(open('RESULTS.json'));print('keys ok:', sorted(d)==sorted(['category_totals_eur','q2_total_eur','mom_may_pct','mom_jun_pct','largest_txn_eur','mean_txn_eur','travel_share_pct','over_budget']))"

tr -d '\r' < transactions.csv | tail -n +2 | awk -F, '
BEGIN{r["EUR"]=1.00; r["USD"]=0.92; r["GBP"]=1.17}
{ if(!($6 in r)){print "UNKNOWN CURRENCY:", $0 > "/dev/stderr"; bad=1}
  e=sprintf("%.2f", $5*r[$6]); c[$3]+=e; m[substr($2,1,7)]+=e; t+=e; n++; if(e+0>mx) mx=e+0 }
END{
  printf "total=%.2f n=%d mean=%.2f max=%.2f\n", t, n, t/n, mx
  printf "may=%.1f jun=%.1f travel_share=%.1f\n", (m["2026-05"]-m["2026-04"])/m["2026-04"]*100, (m["2026-06"]-m["2026-05"])/m["2026-05"]*100, c["travel"]/t*100
  for(k in c) printf "  %s=%.2f\n", k, c[k]
}'
echo "=== half-cent tie check ==="
tr -d '\r' < transactions.csv | tail -n +2 | awk -F, 'BEGIN{r["EUR"]=1;r["USD"]=0.92;r["GBP"]=1.17}{v=$5*r[$6]*1000; d=v-int(v); if((int(v)%10==5 && d<1e-9)) print "TIE:", $0}'
echo "(no TIE lines = half-up vs banker's rounding cannot change any figure)"
